#!/bin/sh
#
# Regenerates cx-local.patch from the current state of 3rdparty/mbedtls.
#
# The patch is the authoritative record of every cx-local change to the
# vendored tree: extract the pinned release pristine, diff the working tree
# against it, write the result. Run this after editing anything under
# 3rdparty/mbedtls. Never hand-edit cx-local.patch.
#
# Environment:
#   MBEDTLS_TARBALL=<path>   reuse an already-downloaded tarball

. "$(dirname "$0")/common.sh"

[ -d "$VENDOR_DIR" ] || die "$VENDOR_DIR does not exist"

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT INT TERM

TARBALL=$(fetch_tarball "$WORK")
extract_pristine "$TARBALL" "$WORK/a"

# diff wants both trees side by side under names that become the a/ and b/
# prefixes `git apply -p1` strips, so the vendored tree is copied rather than
# diffed in place.
cp -a "$VENDOR_DIR" "$WORK/b"

OUT="$CXMBED_DIR/cx-local.patch"

# diff exits 1 when it finds differences, which is the expected case here;
# anything above that is a real failure.
_rc=0
( cd "$WORK" && LC_ALL=C diff -ruN a b ) > "$WORK/diff.raw" || _rc=$?
[ "$_rc" -le 1 ] || die "diff failed with status $_rc"
[ -s "$WORK/diff.raw" ] || die "no local changes found; refusing to write an empty patch"

# Strip the mtimes diff puts after the tab on ---/+++ lines. They carry no
# information -- b/ is whenever the tree was last written -- and leaving them in
# makes cx-local.patch churn on every vendor/refresh cycle even when nothing
# changed, which is exactly the signal this file exists to give. git apply does
# not need them.
LC_ALL=C sed -E 's/^(---|\+\+\+) ([^\t]*)\t.*/\1 \2/' "$WORK/diff.raw" > "$WORK/diff.out"

{
    echo "# cx-local changes against Mbed TLS $VERSION (see README.md)."
    echo "# Generated by refresh.sh -- do not edit by hand."
    cat "$WORK/diff.out"
} > "$OUT"

echo "Wrote $OUT ($(grep -c '^diff -ruN' "$OUT") files changed)." >&2
